content:
150                  buffer = &pac->pac->Buffers[i];
   151              else
   152                  return EINVAL;
   153          }
   154      }
   155
   156      if (buffer == NULL)
   157          return ENOENT;
   158
   159      assert(buffer->Offset + buffer->cbBufferSize <= pac->data.length);
   160
   161      if (data != NULL) {
   162          data->length = buffer->cbBufferSize;
   163          data->data = pac->data.data + buffer->Offset;
   164      }
   165
   166      return 0;
   167  }
