   169  /*
   170   * Find a buffer and copy data into output
   171   */
   172  krb5_error_code KRB5_CALLCONV
   173  krb5_pac_get_buffer(krb5_context context,
   174                      krb5_pac pac,
   175                      krb5_ui_4 type,
   176                      krb5_data *data)
   177  {
   178      krb5_data d;
   179      krb5_error_code ret;
   180
   181      ret = k5_pac_locate_buffer(context, pac, type, &d);
   182      if (ret != 0)
   183          return ret;
   184
   185      data->data = k5memdup(d.data, d.length, &ret);
   186      if (data->data == NULL)
   187          return ret;
   188      data->length = d.length;
   189
   190      return 0;
   191  }
