   193  /*
   194   * Return an array of the types of data in the PAC
   195   */
   196  krb5_error_code KRB5_CALLCONV
   197  krb5_pac_get_types(krb5_context context,
   198                     krb5_pac pac,
   199                     size_t *len,
   200                     krb5_ui_4 **types)
   201  {
   202      size_t i;
   203
   204      *types = (krb5_ui_4 *)malloc(pac->pac->cBuffers * sizeof(krb5_ui_4));
   205      if (*types == NULL)
   206          return ENOMEM;
   207
   208      *len = pac->pac->cBuffers;
   209
   210      for (i = 0; i < pac->pac->cBuffers; i++)
   211          (*types)[i] = pac->pac->Buffers[i].ulType;
   212
   213      return 0;
   214  }
