   216  /*
   217   * Initialize PAC
   218   */
   219  krb5_error_code KRB5_CALLCONV
   220  krb5_pac_init(krb5_context context,
   221                krb5_pac *ppac)
   222  {
   223      krb5_pac pac;
   224
   225      pac = (krb5_pac)malloc(sizeof(*pac));
   226      if (pac == NULL)
   227          return ENOMEM;
   228
   229      pac->pac = (PACTYPE *)malloc(sizeof(PACTYPE));
   230      if (pac->pac == NULL) {
   231          free(pac);
   232          return ENOMEM;
   233      }
   234
   235      pac->pac->cBuffers = 0;
   236      pac->pac->Version = 0;
   237
   238      pac->data.length = PACTYPE_LENGTH;
   239      pac->data.data = calloc(1, pac->data.length);
   240      if (pac->data.data == NULL) {
   241          krb5_pac_free(context, pac);
   242          return ENOMEM;
   243      }
   244
   245      pac->verified = FALSE;
   246
   247      *ppac = pac;
   248
   249      return 0;
   250  }
